package adminui

import (
	"encoding/json"
	"net/http"

	"antigravity-gateway/internal/config"
	"antigravity-gateway/internal/server"
)

const page = `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no"><title>API网关配置</title><style>
*{box-sizing:border-box;margin:0;padding:0}body{background:#f5f5f7;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;padding:8px 10px;color:#222}.container{max-width:620px;margin:0 auto}.card{background:#fff;border-radius:18px;padding:14px;margin-bottom:10px;box-shadow:0 1px 2px #0000000f}.hidden{display:none!important}.card-title-row,.app-row{display:flex;justify-content:space-between;align-items:flex-start;gap:12px}.top-label,.section-label,.app-text .label,.result-label{font-size:12px;color:#777}.main-title{font-size:18px;font-weight:600}.right-link,.copy-text,.url{font-size:13px;color:#0666cc;font-weight:500}.field{position:relative;margin-top:20px}.field-label{position:absolute;left:16px;top:-9px;background:#fff;padding:0 5px;color:#666;font-size:12px;z-index:2}.field-input{width:100%;border:1.5px solid #b0b2b5;border-radius:12px;padding:10px 14px;font-size:14px;line-height:1.4;background:#fff;color:#222;outline:none}.field-input:focus{border-color:#1c78e6}.password-wrap{position:relative}.eye-icon{position:absolute;right:14px;top:50%;transform:translateY(-50%);width:24px;height:24px;cursor:pointer;z-index:2}.section-space{margin-top:16px}.key-row,.test-btn-row{display:flex;gap:8px;align-items:center}.key-input-box{position:relative;width:180px;flex-shrink:0}.btn,.test-btn{flex:1;border:1px solid #d2d4d8;background:#fff;border-radius:10px;font-size:13px;color:#0666cc;padding:10px 6px;cursor:pointer;white-space:nowrap}.danger{color:#c0392b}.key-list{display:grid;gap:8px;margin-top:10px}.key-item{border:1px solid #e5e6e8;border-radius:12px;padding:10px}.key-item strong{font-size:14px}.key-item small{display:block;color:#777;margin-top:3px;overflow-wrap:anywhere}.key-actions{display:flex;gap:8px;margin-top:8px}.key-actions button{flex:0 0 auto}.start-btn{width:100%;background:#1c78e6;color:#fff;border:none;border-radius:16px;padding:12px 0;font-size:15px;font-weight:500;margin-bottom:10px;cursor:pointer}.test-title{font-size:15px;font-weight:600;margin-bottom:10px}.result-box{background:#f0f2f5;border-radius:10px;padding:10px 12px;font-size:13px;color:#333;line-height:1.4;white-space:pre-wrap;overflow-wrap:anywhere;min-height:42px}.status{font-size:12px;margin-top:8px;white-space:pre-wrap}.ok{color:#388e3c}.bad{color:#d32f2f}.login{max-width:400px;margin:15vh auto 0}.login h1{margin-bottom:6px}.logout{float:right;color:#0666cc;cursor:pointer;font-size:13px}@media(max-width:430px){.container{max-width:350px}.key-row{align-items:stretch;flex-wrap:wrap}.key-input-box{width:100%}.key-row .btn{min-width:calc(50% - 4px)}.app-row{align-items:flex-end}.test-btn-row{gap:8px}}
</style></head><body><div id="login" class="container login card"><h1>API网关配置</h1><div class="top-label">管理员登录</div><div class="field"><label class="field-label">管理员密码</label><div class="password-wrap"><input id="loginKey" type="password" class="field-input" autocomplete="current-password" placeholder="输入管理员密码"><span class="eye-icon" data-eye="loginKey">◉</span></div></div><button class="start-btn" onclick="login()">进入管理页面</button><div id="loginStatus" class="status bad"></div></div><div id="dashboard" class="container hidden"><div class="card"><div class="card-title-row"><div><div class="top-label">当前供应商</div><div class="main-title">服务器网关<span class="pencil">✏</span></div></div><div class="right-link">服务器配置</div></div></div><div class="card"><div class="field"><label class="field-label">上游 URL</label><input id="upstreamURL" class="field-input" placeholder="输入上游 URL"></div><div class="field"><label class="field-label">上游 Key</label><div class="password-wrap"><input id="upstreamKey" type="password" class="field-input" placeholder="输入上游 Key"><span class="eye-icon" data-eye="upstreamKey">◉</span></div></div><div class="field"><label class="field-label">认证方式</label><select id="authMode" class="field-input"><option value="bearer">Bearer Key</option><option value="none">无认证</option></select></div><button class="start-btn" onclick="saveUpstream()">保存上游配置</button><div id="upstreamStatus" class="status"></div></div><div class="card"><div class="section-label">全局下游 Key</div><div class="key-row" style="margin-top:8px"><div class="key-input-box password-wrap"><input id="downKey" type="password" class="field-input" placeholder="生成后显示"><span class="eye-icon" data-eye="downKey">◉</span></div><button class="btn" onclick="createKey()">生成</button><button class="btn" onclick="copyDownKey()">复制</button></div><div id="keyStatus" class="status"></div></div><div class="card"><div class="app-row"><div class="app-text"><div class="label">应用链接</div><div id="appURL" class="url"></div></div><div class="copy-text" onclick="copyText(location.origin+'/v1','keyStatus')">复制</div></div></div><div class="card"><div class="card-title-row"><div class="section-label">已注册下游 Key</div><button class="btn" style="flex:0 0 auto" onclick="loadKeys()">刷新</button></div><div id="keys" class="key-list"></div></div><div class="card"><div class="test-title">功能测试与状态</div><div class="test-btn-row"><button class="btn" onclick="loadModels()">拉取模型</button><button class="btn" onclick="messageTest()">消息测试</button></div><div class="field"><label class="field-label">输入模型 ID (例如 gpt-4o)</label><input id="model" class="field-input" placeholder=""></div><div class="result-label">测试结果</div><div id="result" class="result-box">网关状态读取中…</div><div class="field"><label class="field-label">测试消息</label><input id="prompt" class="field-input" placeholder="输入消息"></div><span class="logout" onclick="logout()">退出管理</span></div></div><script>
let adminToken='';const $=id=>document.getElementById(id);$('appURL').textContent=location.origin+'/v1';document.querySelectorAll('[data-eye]').forEach(e=>e.onclick=()=>{const i=$(e.dataset.eye);i.type=i.type==='password'?'text':'password';e.style.color=i.type==='password'?'#777':'#333'});function msg(id,text,good=false){$(id).textContent=text;$(id).className='status '+(good?'ok':'bad')}async function copyText(v,id){try{if(navigator.clipboard&&window.isSecureContext)await navigator.clipboard.writeText(v);else{const t=document.createElement('textarea');t.value=v;t.style.position='fixed';t.style.opacity='0';document.body.appendChild(t);t.select();if(!document.execCommand('copy'))throw Error();t.remove()}msg(id,'已复制',true)}catch(e){msg(id,'复制失败，请手动选择文本')}}async function api(path,opt={}){opt.headers=Object.assign({'Authorization':'Bearer '+adminToken,'Content-Type':'application/json'},opt.headers||{});const r=await fetch(path,opt);const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error?.message||'HTTP '+r.status);return d}async function login(){adminToken=$('loginKey').value.trim();try{await api('/admin/keys');$('login').classList.add('hidden');$('dashboard').classList.remove('hidden');await loadKeys();loadRuntime()}catch(e){adminToken='';msg('loginStatus','管理员密码错误或服务未就绪')}}function logout(){adminToken='';$('dashboard').classList.add('hidden');$('login').classList.remove('hidden');$('loginKey').value=''}async function loadRuntime(){try{const d=await api('/admin/runtime');$('upstreamURL').value=d.base_url||'';$('authMode').value=d.auth_mode||'bearer';$('upstreamKey').value=d.api_key||''}catch(e){}}async function saveUpstream(){try{await api('/admin/runtime',{method:'PUT',body:JSON.stringify({base_url:$('upstreamURL').value,api_key:$('upstreamKey').value,auth_mode:$('authMode').value})});msg('upstreamStatus','上游配置已热更新',true)}catch(e){msg('upstreamStatus','保存失败：'+e.message)}}async function createKey(){try{const name=prompt('请输入 Key 名称或用途（可留空）')||'';const d=await api('/admin/keys',{method:'POST',body:JSON.stringify({name})});$('downKey').value=d.key;msg('keyStatus','已生成新 Key，请复制保存',true);await loadKeys()}catch(e){msg('keyStatus','生成失败：'+e.message)}}async function copyDownKey(){if(!$('downKey').value){msg('keyStatus','请先生成或选择 Key');return}await copyText($('downKey').value,'keyStatus')}async function loadKeys(){try{const d=await api('/admin/keys');$('keys').innerHTML=(d.data||[]).map(k=>'<div class="key-item"><strong>'+esc(k.name)+'</strong><small>'+esc(k.key_prefix)+' · '+esc(k.status)+'</small><div class="key-actions">'+(k.can_reveal?'<button class="btn" onclick="revealKey(\''+esc(k.id)+'\')">复制完整 Key</button>':'')+'<button class="btn danger" onclick="deleteKey(\''+esc(k.id)+'\')">删除</button></div></div>').join('')||'<small>暂无 Key</small>'}catch(e){$('keys').textContent='读取失败：'+e.message}}async function revealKey(id){try{const d=await api('/admin/keys/'+encodeURIComponent(id)+'/reveal');$('downKey').value=d.key;await copyText(d.key,'keyStatus')}catch(e){msg('keyStatus','无法读取 Key：'+e.message)}}async function deleteKey(id){if(!confirm('确定删除此 Key？删除后立即失效且无法恢复。'))return;try{await api('/admin/keys/'+encodeURIComponent(id),{method:'DELETE'});$('downKey').value='';msg('keyStatus','Key 已删除',true);await loadKeys()}catch(e){msg('keyStatus','删除失败：'+e.message)}}async function loadModels(){try{const d=await api('/v1/models',{headers:{Authorization:'Bearer '+$('downKey').value}});$('result').textContent='模型数量：'+(d.data||[]).length+'\n'+(d.data||[]).map(x=>x.id).join(', ')}catch(e){$('result').textContent='模型读取失败：'+e.message}}async function messageTest(){try{const r=await fetch('/v1/chat/completions',{method:'POST',headers:{Authorization:'Bearer '+$('downKey').value,'Content-Type':'application/json'},body:JSON.stringify({model:$('model').value,messages:[{role:'user',content:$('prompt').value}],stream:false})});$('result').textContent=await r.text()}catch(e){$('result').textContent='消息测试失败：'+e.message}}function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
</script></body></html>`

func Handler(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	_, _ = w.Write([]byte(page))
}

func RuntimeHandler(cfg *config.Config) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		base, key, mode := cfg.UpstreamSettings()
		server.WriteJSON(w, http.StatusOK, map[string]any{"base_url": base, "api_key": key, "auth_mode": mode})
	}
}
func RuntimeUpdateHandler(cfg *config.Config) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		var req config.UpstreamSettings
		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
			server.WriteError(w, 400, "invalid JSON", "invalid_request_error", "bad_request")
			return
		}
		if err := cfg.UpdateUpstream(req); err != nil {
			server.WriteError(w, 400, err.Error(), "invalid_request_error", "invalid_config")
			return
		}
		server.WriteJSON(w, 200, map[string]string{"status": "updated"})
	}
}
